# Initially generated by GitHub Copilot.
"""Download Aleppo Codex page images (leaves 270-281) from archive.org.

Downloads the 24 page images (recto and verso for each leaf) into
``aleppo/aleppo-pages/``, skipping any that already exist. Those
images are DOWNLOADED rather than generated, so no check regenerates them and
nothing else in this repo writes that directory.

Usage:
    .venv/Scripts/python.exe py/main_ac_download_pages.py

WHY THIS FILE HAS A ``main()`` NOW.  It was ``py/download_aleppo_pages.py`` in
codex-index-aleppo until Phase 3 of
``doc/PLAN-evacuate-python-from-codex-index-trio.md``, 2026-08-22, and the whole of
it -- the ``os.makedirs``, the loop, the network reads -- ran at MODULE SCOPE, with
no ``main()`` and no ``if __name__`` guard.  Harmless in a repo whose only entry
into it was to run it; not harmless in MAM-basics, where importing a top-level
module to inspect it is ordinary and would have started twenty-four downloads.
Phase 1 of the same plan noted the hazard and left it, that phase being about paths.
"""

import os
from urllib.request import Request, urlopen

from mb_cmn.url_percent import pct_path_component
from wlc_cmn.utf8_io import force_utf8_io

import ac_paths

_ZIP_MEMBER = "/7/items/aleppo-codex/Aleppo Codex_jp2.zip"

# Leaves 270-281, recto and verso
PAGE_IDS = [f"{leaf}{side}" for leaf in range(270, 282) for side in ("r", "v")]


def almost_main() -> None:
    """The body, callable in-process."""
    out_dir = ac_paths.pages_dir()
    os.makedirs(out_dir, exist_ok=True)
    for page_id in PAGE_IDS:
        page_n = _leaf_to_page_n(page_id)
        out_path = out_dir / f"{page_id}.jpg"
        if out_path.exists():
            print(f"  Already exists: {out_path}")
            continue
        print(f"  Downloading {page_id} (archive page {page_n}) ...")
        req = Request(_archive_image_url(page_n), headers={"User-Agent": "Mozilla/5.0"})
        with urlopen(req, timeout=120) as resp:
            data = resp.read()
        out_path.write_bytes(data)
        print(f"    Saved {len(data)} bytes -> {out_path}")
    print("Done.")


def _leaf_to_page_n(page_id):
    """Convert a leaf ID like '270r' to the archive.org 0-based page index."""
    num = int(page_id[:-1])
    side = page_id[-1]
    return (num - 1) * 2 + 2 + (0 if side == "r" else 1)


def _archive_image_url(page):
    zip_part = pct_path_component(_ZIP_MEMBER, safe="/")
    file_member = f"Aleppo Codex_jp2/Aleppo Codex_{page:04d}.jp2"
    file_part = pct_path_component(file_member, safe="/")
    return (
        "https://ia601801.us.archive.org/BookReader/BookReaderImages.php"
        f"?zip={zip_part}&file={file_part}&id=aleppo-codex&scale=2&rotate=0"
    )


if __name__ == "__main__":
    force_utf8_io()
    almost_main()
